html:
{%- set company_logo_url = doc.company_logo or "/files/OMSteel.png" -%}

{%- set customer_name = doc.quality_m_customer_name -%}
{%- set so_no = doc.quality_m_sales_order_no -%}
{%- set date = doc.quality_m_certificate_date -%}
{%- set test_type = doc.quality_m_test_type -%}
{%- set certificate_no = doc.quality_m_certificate_no -%}
{%- set certificate_date = doc.quality_m_certificate_date -%}
{%- set child_table_items = doc.quality_certificate_item_chield -%} 

<style>
    @media print {
        @page {
            size: A4 landscape;
            margin: 10mm;
        }
    }

    .print-format-custom {
        font-family: 'Cairo', sans-serif;
        font-size: 10px;
        color: #000;
        width: 100%;
        direction: ltr;
    }
    
    .print-format-custom table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 10px;
    }
    
    .print-format-custom th, .print-format-custom td {
        border: 1px solid #000;
        padding: 4px;
        text-align: center;
        vertical-align: middle;
        color: #000 !important; 
        font-weight: bold !important;
    }

    .bg-blue {
        background-color: #8bc1e8 !important; 
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }

    .bilingual-cell {
        padding: 4px 6px !important;
    }
    .bilingual-cell .en {
        display: block;
        text-align: left;
    }
    .bilingual-cell .ar {
        display: block;
        text-align: right;
        direction: rtl;
    }
    
    .company-header {
        width: 100%;
        margin-bottom: 15px;
        border: none;
    }
    .company-header td {
        border: none;
        padding: 2px;
        text-align: left;
    }
    .company-header .ar-text {
        text-align: right;
        direction: rtl;
    }
    .title-cert {
        text-align: center !important;
        font-size: 16px;
        font-weight: bold;
    }

    .company-logo {
        max-width: 80px !important;
        height: auto;
    }
    
    .stamps-container {
        text-align: center;
        white-space: nowrap;
    }
    .stamps-img {
        height: 35px;
        display: inline-block;
        vertical-align: middle;
        margin: 0 5px;
    }
    .manual-stamp-space {
        display: inline-block;
        width: 40px;
        height: 35px;
        vertical-align: middle;
    }
</style>

<div class="print-format-custom">

    <!-- Header: Company Info & Logo -->
    <table class="company-header">
        <tr>
            <td width="33%">
                <img src="{{ company_logo_url }}" class="company-logo" alt="Company Logo"><br>
                <b>Obaid Waid AL Harbi & Mohamed Salem AlSaari Partners Co.Ltd</b><br>
                P.O . Box No.36499<br>
                Jedda , KSA<br>
                <span style="color: #0070C0;">TEL:0126082223</span>
            </td>
            <td width="34%" class="title-cert">
                QUALITY CERTIFICATE<br><br>
                شهادة جودة
            </td>
            <td width="33%" class="ar-text">
                <br>
                <b>شركة مصنع عبيد ويد عبيد المستادي الحربي ومحمد سالم محمد الصاعري وشركاهما</b><br>
                ص.ب. 36499<br>
                جدة المملكة العربية السعودية<br>
                <span style="color: #0070C0;">تلفون: 0126082223</span>
            </td>
        </tr>
    </table>

    <!-- Meta Data Table (Header Data) -->
    <table>
        <tr>
            <td class="bg-blue bilingual-cell" width="15%">
                <span class="en">CUSTOMER NAME</span>
                <span class="ar">اسم العميل</span>
            </td>
            <td width="18%">{{ customer_name }}</td>
            
            <td class="bg-blue bilingual-cell" width="15%">
                <span class="en">TEST TYPE</span>
                <span class="ar">نوع الاختبار</span>
            </td>
            <td width="18%">{{ test_type }}</td>
            
            <td class="bg-blue bilingual-cell" width="16%">
                <span class="en">CERTIFICATE NO</span>
                <span class="ar">رقم الشهادة</span>
            </td>
            <td width="18%">{{ certificate_no }}</td>
        </tr>
        <tr>
            <td class="bg-blue bilingual-cell">
                <span class="en">So. NO</span>
                <span class="ar">رقم امر البيع</span>
            </td>
            <td>{{ so_no }}</td>
            
            <td class="bg-blue bilingual-cell">
                <span class="en">STANDARDS</span>
                <span class="ar">المواصفات</span>
            </td>
            <td>{{ standards }}</td>
            
            <td class="bg-blue bilingual-cell">
                <span class="en">CERTIFICATE</span>
                <span class="ar">تاريخ الشهادة</span>
            </td>
            <td>{{ certificate_date }}</td>
        </tr>
        <tr>
            <td class="bg-blue bilingual-cell">
                <span class="en">DATE</span>
                <span class="ar">التاريخ</span>
            </td>
            <td>{{ date }}</td>
            
            <td class="bg-blue bilingual-cell">
                <span class="en">STEEL GRADE</span>
                <span class="ar">درجة الحديد</span>
            </td>
            <td>{{ steel_grade }}</td>
            
            <td class="bg-blue"></td>
            <td></td>
        </tr>
    </table>

    <!-- Main Data Table (Child Doctype) -->
    <table>
        <thead>
            <tr class="bg-blue">
                <th rowspan="2">Heat No.<br><br>رقم الصب</th>
                <th rowspan="1">SIZE<br><br>الابعاد</th>
                <th rowspan="1">Thickness<br><br>السماكة</th>
                <th rowspan="1">Length<br><br>الطول</th>
                <th rowspan="1">QTY.<br><br>عدد القطع</th>
                <th rowspan="2">Visual &<br>Dimension<br>test<br><br>اختبار الابعاد<br>و البصري</th>
                <th rowspan="2">BEND<br>TEST<br><br>اختبار<br>الثني</th>
                <th colspan="3">MECHANICAL PROPERTIES<br><br>الخصائص الميكانيكية</th>
                <th colspan="6">CHEMICAL COMPOSITION<br><br>نسبة التركيبة الكيميائية</th>
            </tr>
            <tr class="bg-blue">
                <!-- Units Row -->
                <th>(mm)</th>
                <th>(mm)</th>
                <th>meter</th>
                <th>PCS</th>
                
                <!-- Mechanical Sub -->
                <th>YS.<br>مقاومة الخضوع<br>(N/mm2)</th>
                <th>TS.<br>مقاومة الشد<br>(N/mm2)</th>
                <th>EL.<br>نسبة الاستطالة<br>%</th>
                
                <!-- Chemical Sub -->
                <th>C<br>كربون<br>%</th>
                <th>Si<br>سيليكون<br>%</th>
                <th>Mn<br>منجنيز<br>%</th>
                <th>P<br>فوسفور<br>%</th>
                <th>S<br>كبريت<br>%</th>
                <th>Cu<br>نحاس<br>%</th>
            </tr>
        </thead>
        <tbody>
            {% for row in child_table_items %}
            <tr>
                <td>{{ row.quality_m_heat_no or "" }}</td>
                <td>{{ row.quality_m_size or "" }}</td>
                <td>{{ row.quality_m_thickness or "" }}</td>
                <td>{{ row.quality_m_length or "" }}</td>
                <td>{{ row.quality_m_qty or "" }}</td>
                <td>{{ row.quality_m_bend_test or "-" }}</td>
                
                <td>{{ row.quality_m_ys_yield_strength_nmm2 or "" }}</td>
                <td>{{ row.quality_m_ts_tensile_strength_nmm2 or "" }}</td>
                <td>{{ row.quality_m_el_elongation_ or "" }}</td>
                
                <td>{{ row.quality_m_c__carbon or "" }}</td>
                <td>{{ row.quality_m_si__silicon or "" }}</td>
                <td>{{ row.quality_m_mn__manganese or "" }}</td>
                <td>{{ row.quality_m_p__phosphorus or "" }}</td>
                <td>{{ row.quality_m_s__sulfur or "" }}</td>
                <td>{{ row.quality_m_cu__copper or "-" }}</td>
                <td>{{ row.quality_m_al__aluminum or "-" }}</td>
            </tr>
            {% endfor %}
            
            {% for i in range(5 - (child_table_items|length if child_table_items else 0)) %}
            <tr>
                <td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td>
                <td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- Footer Section -->
    <div style="font-size: 11px; margin-bottom: 5px; font-weight: bold; color: #000;">
        T.S: Tensile Strength, Y.S: Yield Strength, EL: Elongation,
    </div>

    <table style="margin-bottom: 0;">
        <tr>
            <td width="20%" style="font-weight: bold; text-align: center;">QUALITY ASSURANCE</td>
            <td width="50%" style="text-align: center;">
                <b>We hereby certify that the material described has been manufactured as per above standards.</b><br><br>
                <b style="direction: rtl;">نشهد على أن المواد الموصوفة قد تم تصنيعها وفقا للمعايير المذكورة أعلاه</b>
            </td>
            <td width="30%" style="text-align: center; border: 1px solid #000;">
                <div class="stamps-container">
                    <img src="/files/IAF_Stamp.png" class="stamps-img" alt="IAF Stamp">
                    <img src="/files/UAF Stamp.png" class="stamps-img" alt="UAF Stamp">
                    <div class="manual-stamp-space"></div>
                </div>
            </td>
        </tr>
    </table>
    
    <div style="font-size: 10px; font-weight: bold; margin-top: 5px; color: #000;">
        F-08.2-11 Issue: 3
    </div>

</div>
